// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        address rewardToken = address(0x1);
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("addReward(address)", rewardToken));
        assertTrue(!success, "Non-owner should not be able to addReward");
    }
}

